import{_ as a,o as t,c as p,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-083.2D7veA6U.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/71-性格决定阶层吗？.md","filePath":"books/xialiu-shehui/71-性格决定阶层吗？.md","lastUpdated":1794732511000}'),_={name:"books/xialiu-shehui/71-性格决定阶层吗？.md"};function i(r,e,l,n,d,c){return t(),p("div",null,[...e[0]||(e[0]=[s('<h2 id="性格决定阶层吗" tabindex="-1">性格决定阶层吗？ <a class="header-anchor" href="#性格决定阶层吗" aria-label="Permalink to &quot;性格决定阶层吗？&quot;">​</a></h2><p>前述的知名自我封闭研究者、精神科医生斋藤环指出，阶层差距是由人际沟通能力的差距造成的：“决定胜败的关键因素之一，很明显就是沟通……被视为不擅长沟通的孩子，很容易心灰意冷地将自己归入‘败组’……这种沟通能力上的差距如果任其发展下去的话，最终结果便是导致自我封闭一类的问题，这绝不是危言耸听。”（参见斋藤环著《“败者教”的信者们》）</p><p>此外，教育社会学家、东京大学副教授本田由纪在分析年轻人的生活技能时也指出，就诸如“向别人说明自己的意见”“和不熟悉的人自然地交谈”等沟通能力而言，学历越高的人，其沟通能力也越强（参见本田由纪《社会自立与生活技能》，摘自日本内阁府《关于青少年社会自立意识的调查报告书》）。</p><p>“欲求调查”的结果也可以在某种程度上印证上述倾向。如同前面已经分析过的，团块次代的下流阶层，不论男女都强烈倾向于认为一个人独处是一种幸福。</p><p>此外，当被问及有关被调查者本人性格方面的问题时，上流阶层的男性回答“常常以为最后有谁可以为我做些什么”的人数为零，而回答“已经决定的事会立即行动”“觉得自己的性格比较开朗”“没有什么特别喜欢或讨厌的人”“对周围人的态度、情绪变化相当敏感”的比较多；反之对于“觉得自己的性格比较开朗”这个问题，下流阶层中回答“符合”的人所占的比例非常小（见表7-1）。</p><p>表7-1　团块次代不同阶层对自己性格的评价（主要选项）包括“同意”或“基本上同意”</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>换句话说，上流阶层的男性性格比较开朗，没有什么特别喜欢或特别讨厌的人，他们人际关系好、处事谨慎、有执行能力，依赖性较弱，而下流阶层的男性性格比较忧郁、优柔寡断、有着很强的依赖性。</p><p>简单地说，上流阶层的男性颇像是一个组织中的领导者，大多属于运动型，而下流阶层男性中属于这一类型的人很少。这就意味着，在团块次代男性的身上还残留着浓厚的传统的性别意识，并且深深为这种意识所束缚。</p><p>相形之下，女性在这方面不像男性那样有着明显的阶层差距，然而上流阶层的女性很少有人回答“常常以为最后有谁可以为我做些什么”，这一点与男性是相同的。此外，上流阶层中有很多女性认为自己的性格“能够将周围人的能力和长处发挥出来”“为了引人注目，会有许多标显的言行举止”。</p><p>从上表中可以看出，女性与男性相反，阶层越是“上流”，就越没有所谓传统女性的样子，也越没有性别意识，反而有着与男性稍稍相似的领导者一般的性格。</p>',12)])])}const m=a(_,[["render",i]]);export{h as __pageData,m as default};
